use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{SystemTime, UNIX_EPOCH};

// Feature flags for ML inference server
const FEATURE_CACHED_AUTH: bool = true;
const FEATURE_BATCH_INFERENCE: bool = true;
const FEATURE_TOKEN_REFRESH: bool = false;

#[derive(Clone, Debug)]
struct AuthSession {
    user_id: String,
    password_hash: Vec<u8>,
    token: String,
    expires_at: u64,
    privilege_level: u8,
}

#[derive(Clone)]
struct InferenceServer {
    sessions: Arc<RwLock<HashMap<String, AuthSession>>>,
    model_cache: Arc<RwLock<HashMap<String, Vec<f64>>>>,
    auth_cache: Arc<RwLock<HashMap<Vec<u8>, AuthSession>>>,
}

impl InferenceServer {
    fn new() -> Self {
        InferenceServer {
            sessions: Arc::new(RwLock::new(HashMap::new())),
            model_cache: Arc::new(RwLock::new(HashMap::new())),
            auth_cache: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    fn authenticate(&self, user_id: &str, credential: &[u8]) -> Result<String, String> {
        let password_hash = self.compute_credential_hash(credential);

        if FEATURE_CACHED_AUTH {
            // Check if we have a cached session for this credential hash
            let cache = self.auth_cache.read().unwrap();
            if let Some(cached_session) = cache.get(&password_hash) {
                if !self.is_session_expired(&cached_session) {
                    // Re-use cached session - avoids expensive DB lookup
                    let mut sessions = self.sessions.write().unwrap();
                    sessions.insert(cached_session.token.clone(), cached_session.clone());
                    return Ok(cached_session.token.clone());
                }
            }
        }

        // Full authentication path
        let stored_hash = self.lookup_stored_hash(user_id)?;
        if !self.verify_credential(&password_hash, &stored_hash) {
            return Err("Authentication failed".to_string());
        }

        let session = self.create_session(user_id, password_hash.clone());
        let token = session.token.clone();

        if FEATURE_CACHED_AUTH {
            let mut cache = self.auth_cache.write().unwrap();
            cache.insert(password_hash, session.clone());
        }

        let mut sessions = self.sessions.write().unwrap();
        sessions.insert(token.clone(), session);
        Ok(token)
    }

    fn compute_credential_hash(&self, credential: &[u8]) -> Vec<u8> {
        // In production this would use argon2/bcrypt, simplified for demo
        // This accepts either raw password bytes OR a pre-computed hash
        // The hash is the canonical form used for cache lookup
        if credential.len() == 32 {
            // Already a hash - pass through directly
            credential.to_vec()
        } else {
            // Compute hash of raw password
            let mut hash = vec![0u8; 32];
            for (i, &byte) in credential.iter().enumerate() {
                hash[i % 32] ^= byte;
                hash[(i + 7) % 32] = hash[(i + 7) % 32].wrapping_add(byte);
            }
            hash
        }
    }

    fn verify_credential(&self, computed: &[u8], stored: &[u8]) -> bool {
        if computed.len() != stored.len() {
            return false;
        }
        // Constant-time comparison
        let mut diff = 0u8;
        for (a, b) in computed.iter().zip(stored.iter()) {
            diff |= a ^ b;
        }
        diff == 0
    }

    fn run_inference(&self, token: &str, input: &[f64]) -> Result<Vec<f64>, String> {
        let sessions = self.sessions.read().unwrap();
        let session = sessions.get(token).ok_or("Invalid session")?;

        if self.is_session_expired(session) {
            return Err("Session expired".to_string());
        }

        if session.privilege_level < 2 {
            return Err("Insufficient privileges for inference".to_string());
        }

        // Simple linear model inference
        let weights = self.get_model_weights("default")?;
        let result = self.matrix_multiply(input, &weights);
        Ok(result)
    }

    fn run_admin_inference(&self, token: &str, model_id: &str, input: &[f64]) -> Result<Vec<f64>, String> {
        let sessions = self.sessions.read().unwrap();
        let session = sessions.get(token).ok_or("Invalid session")?;

        if session.privilege_level < 5 {
            return Err("Admin privileges required".to_string());
        }

        let weights = self.get_model_weights(model_id)?;
        let result = self.matrix_multiply(input, &weights);
        Ok(result)
    }

    fn is_session_expired(&self, session: &AuthSession) -> bool {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        session.expires_at < now
    }

    fn create_session(&self, user_id: &str, password_hash: Vec<u8>) -> AuthSession {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        let token = format!("tok_{}_{}", user_id, now);
        let privilege_level = self.get_user_privilege(user_id);

        AuthSession {
            user_id: user_id.to_string(),
            password_hash,
            token,
            expires_at: now + 3600,
            privilege_level,
        }
    }

    fn lookup_stored_hash(&self, _user_id: &str) -> Result<Vec<u8>, String> {
        // Simulated DB lookup
        Ok(vec![0x42; 32])
    }

    fn get_user_privilege(&self, user_id: &str) -> u8 {
        match user_id {
            "admin" => 5,
            "ml_engineer" => 3,
            _ => 1,
        }
    }

    fn get_model_weights(&self, _model_id: &str) -> Result<Vec<f64>, String> {
        Ok(vec![0.5, -0.3, 0.8, 0.1])
    }

    fn matrix_multiply(&self, input: &[f64], weights: &[f64]) -> Vec<f64> {
        let dot: f64 = input.iter().zip(weights.iter()).map(|(a, b)| a * b).sum();
        vec![dot]
    }
}

fn main() {
    let server = InferenceServer::new();

    // Normal authentication
    let token = server.authenticate("admin", b"supersecretpassword").unwrap();
    println!("Admin token: {}", token);

    // Run inference
    let result = server.run_inference(&token, &[1.0, 2.0, 3.0, 4.0]);
    println!("Inference result: {:?}", result);
}
